void main() {
  group("TrezorPacker", () {
    test("createChunks", () {
      final chunks = TrezorPacker().pack(Uint8List.fromList(data), 244);

      expect(chunks.length, 2);
      expect(chunks.first.first, 0x04);
      expect(chunks.first.length, 244);
      expect(chunks[1].first, 0x80);
      expect(chunks[1].length, 244);

